window.RP_SESSION={"id":"S-f0f0207815b0","messages":[{"id":"RP-0223819","time":"2026-08-11T17:43:00+09:00","room":"RP","name":"션 / 마리우스","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"흐아-압!\"\n\n20년에 가까운 세월을 단련에 투자한 여인의 기합은 하늘이 트인 흥련장을 쩌렁쩌렁 울릴 만큼 커다란 것이었다.\n\n션의 흘려내기에 한차례 땅을 구른 마리우스는 기합과 함께 몸을 튕겨 날이 넓적한 칼을 휘둘렀다.","characters":["P-3bbc4a823df9","P-b6d81d634c6e"]},{"id":"RP-0223820","time":"2026-08-11T17:43:00+09:00","room":"RP","name":"션 / 마리우스","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-3bbc4a823df9","P-b6d81d634c6e"]},{"id":"RP-0223821","time":"2026-08-11T17:43:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'델타인'의 민첩 판정 :\n[2] + [0] = [2]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-0223822","time":"2026-08-11T17:44:00+09:00","room":"RP","name":"션 / 마리우스","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-3bbc4a823df9","P-b6d81d634c6e"]},{"id":"RP-0223823","time":"2026-08-11T17:44:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'션'의 민첩 판정 :\n[8] + [4] = [12]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0223824","time":"2026-08-11T17:45:00+09:00","room":"RP","name":"션 / 마리우스","profile":"델타인","identity":"reviewed","type":"dialogue","body":"쌔앵-\n\n마치 거대한 말벌이 날갯짓을 하는 듯한 진동음과 함께 섬광이 허공을 가로질렀다.\n\n션은 묵직한 한손반검을 대각으로 들어 도격을 막아냈다. 아니, 막아내는 척하다가, 슬쩍 타이밍을 늦추어 상체를 뒤로 젖혔다.\n\n훙!\n\n매서운 기운이 담긴 칼끝이 머리칼을 스치기 무섭게 벼락 같이 검을 들이밀었다. 마리우스가 목표를 놓쳤음을 미처 눈치채기도 전에 한손반검의 묵직한 칼날이 곡도의 칼등에 달라붙었다.","characters":["P-3bbc4a823df9","P-b6d81d634c6e"]},{"id":"RP-0223825","time":"2026-08-11T17:45:00+09:00","room":"RP","name":"션 / 마리우스","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-3bbc4a823df9","P-b6d81d634c6e"]},{"id":"RP-0223826","time":"2026-08-11T17:45:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'션'의 힘 판정 :\n[7] + [4] = [11]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0223827","time":"2026-08-11T17:48:00+09:00","room":"RP","name":"션 / 마리우스","profile":"델타인","identity":"reviewed","type":"dialogue","body":"션은 그대로 손목에 힘을 주었다.\n\n카카각-\n\n나름 베테랑의 경지를 눈앞에 둔 검호답게, 마리우스는 뒤늦게나마 상황을 눈치채고 칼을 거두려 했다. 그러나 이미 한손반검은 곡도의 칼등에 단단히 얽힌 채였다.","characters":["P-3bbc4a823df9","P-b6d81d634c6e"]},{"id":"RP-0223828","time":"2026-08-11T17:48:00+09:00","room":"RP","name":"션 / 마리우스","profile":"델타인","identity":"reviewed","type":"dialogue","body":"!격투 난이도는 3?","characters":["P-3bbc4a823df9","P-b6d81d634c6e"]},{"id":"RP-0223829","time":"2026-08-11T17:48:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'션'의 격투 판정 :\n[4, 1, 5] + [1, 1, 2, 3, 1, 4]\n성공수 : [ 3 ]","characters":[]},{"id":"RP-0223830","time":"2026-08-11T17:50:00+09:00","room":"RP","name":"션 / 마리우스","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"읏, 큽-\"\n\n마리우스는 이를 악물고 물러났으나, 션이 얽힌 칼날을 더 강하게 비틀자 이내 아귀힘이 풀리고 말았다. \n\n쨍!\n\n곡도가 튕겨 나가고 마리우스가 넘어지며 흙먼지를 일으켰다. 이제서야 오늘의 마지막 진검 대련이 끝났다.","characters":["P-3bbc4a823df9","P-b6d81d634c6e"]},{"id":"RP-0223831","time":"2026-08-11T17:57:00+09:00","room":"RP","name":"션 / 마리우스","profile":"델타인","identity":"reviewed","type":"dialogue","body":"\"에고, 허리 아파 죽겠네. 어여 들어가라, 애송이 놈들아.\"\n\n션이 칼을 집어넣으면서 허리를 툭툭 안마했다. 그러면서 그는 생각했다….\n\n다음날에 대련이 있으면 밤에 놀지 말자고.","characters":["P-3bbc4a823df9","P-b6d81d634c6e"]},{"id":"RP-0223832","time":"2026-08-11T17:57:00+09:00","room":"RP","name":"션 / 마리우스","profile":"델타인","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-3bbc4a823df9","P-b6d81d634c6e"]},{"id":"RP-0223833","time":"2026-08-11T17:57:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
